def max_sub_array_sum_repeated(arr, n, k):
    def kadane(a):
        best = cur = a[0]
        for x in a[1:]:
            cur = max(x, cur + x)
            best = max(best, cur)
        return best

    total = sum(arr)
    if k == 1:
        return kadane(arr)

    if total > 0:
        max_prefix = max(sum(arr[:i]) for i in range(1, n + 1))
        max_suffix = max(sum(arr[i:]) for i in range(n))
        return max(kadane(arr), max_suffix + max_prefix + (k - 2) * total)
    else:
        return kadane(arr * 2)
